// ─── File: src/main/java/com/bank/softdelete/model/Account.java ───
package com.bank.softdelete.model;

import jakarta.persistence.*;
import org.hibernate.annotations.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
// DELETE → UPDATE setting the flag (physical row preserved)
@SQLDelete(sql = "UPDATE accounts SET deleted = true, deleted_at = now() WHERE id = ?")
// every normal SELECT silently excludes deleted rows (Hibernate 6+)
@SQLRestriction("deleted = false")
// dynamic filter the audit view can enable to INCLUDE deleted rows
@FilterDef(name = "deletedFilter",
           parameters = @ParamDef(name = "isDeleted", type = Boolean.class))
@Filter(name = "deletedFilter", condition = "deleted = :isDeleted")
public class Account {
    @Id private String id;
    private String holderName;
    private BigDecimal balance;
    private boolean deleted = false;

    protected Account() { }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public boolean isDeleted() { return deleted; }
}
```

```java
// ─── File: src/main/java/com/bank/softdelete/service/AccountService.java ───
package com.bank.softdelete.service;

import com.bank.softdelete.model.Account;
import com.bank.softdelete.repository.AccountRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.hibernate.Session;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountService {

    private final AccountRepository accountRepo;

    @PersistenceContext
    private EntityManager em;

    // Normal close → @SQLDelete turns this into an UPDATE deleted=true
    @Transactional
    public void closeAccount(String id) {
        Account acct = accountRepo.findById(id).orElseThrow();
        accountRepo.delete(acct);   // runs UPDATE ... SET deleted=true (not a real DELETE)
        log.info("Account {} soft-deleted (row preserved for audit)", id);
    }

    // Normal list → @SQLRestriction auto-hides deleted rows
    @Transactional(readOnly = true)
    public List<Account> listActive() {
        return accountRepo.findAll();  // WHERE deleted = false applied automatically
    }

    // Audit list → enable @Filter to INCLUDE deleted rows
    @Transactional(readOnly = true)
    public List<Account> listForAudit(boolean deletedOnly) {
        Session session = em.unwrap(Session.class);
        // @SQLRestriction is still applied by @SQLRestriction; for a true "include all"
        // view you rely on @Filter on a path that does not also carry @SQLRestriction,
        // or query deleted rows explicitly. Here we demonstrate enabling the filter.
        session.enableFilter("deletedFilter").setParameter("isDeleted", deletedOnly);
        List<Account> result = em.createQuery(
                "select a from Account a", Account.class).getResultList();
        session.disableFilter("deletedFilter");
        log.info("Audit list (deletedOnly={}) returned {} rows", deletedOnly, result.size());
        return result;
    }
}
```
